mapper.select:
select id, user_id, doctor_id, title, symptom, description, status, create_time,
       shared_name, shared_age, shared_gender, shared_phone
from consultation

  user_id = #{userId,jdbcType=BIGINT}
  and doctor_id = #{doctorId,jdbcType=BIGINT}

order by id desc

mapper.update:
update consultation
user_id = #{userId,jdbcType=BIGINT}, doctor_id = #{doctorId,jdbcType=BIGINT}, title = #{title,jdbcType=VARCHAR}, symptom = #{symptom,jdbcType=VARCHAR}, description = #{description,jdbcType=VARCHAR}, status = #{status,jdbcType=TINYINT}, create_time = #{createTime,jdbcType=TIMESTAMP}, shared_name = #{sharedName,jdbcType=VARCHAR}, shared_age = #{sharedAge,jdbcType=INTEGER}, shared_gender = #{sharedGender,jdbcType=VARCHAR}, shared_phone = #{sharedPhone,jdbcType=VARCHAR},
where id = #{id,jdbcType=BIGINT}
